dark.css:
/* Moss: a runtime-installed example. Copy this file, change the tokens, install it. */
:root[data-theme="moss"][data-mode="dark"] {
  --color-card: #16211a;
  --color-card-foreground: #e4ebe2;
  --color-popover: #1b2720;
  --color-popover-foreground: #e4ebe2;
  --color-accent: #223029;
  --color-accent-foreground: #eef4ec;
  --color-input: #526b57;
  --color-destructive: #ef9a92;
  --color-background: #101712;
  --color-foreground: #e4ebe2;
  --color-primary: #8fd0a8;
  --color-primary-foreground: #101712;
  --color-muted: #18231c;
  --color-muted-foreground: #a1b0a4;
  --color-border: #2a3a2f;
  --color-ring: #a9dfbd;

  --color-action: #e6ecdf;
  --color-action-foreground: #121a14;
  --color-brand-soft: #1b2d22;
  --color-warning: #e0bd74;
  --color-success: #7dd0a6;
  --color-info: #8fd0a8;

  --color-syntax-comment: #7f907f;
  --color-syntax-keyword: #9fc7ff;
  --color-syntax-string: #96d9a8;
  --color-syntax-number: #e6c77b;
  --color-syntax-function: #8fd0d8;
  --color-syntax-attribute: #d6bcfa;
  --color-syntax-builtin: #79d9c4;
  --color-syntax-meta: #9aa6a0;

  --radius-sm: 0;
  --radius-md: 0;
  --radius-lg: 0;
  --radius-xl: 0;
  --radius-2xl: 0;
  --radius-3xl: 0;

  --shadow-sm: none;
  --shadow-md: none;
  --shadow-lg: none;
  --shadow-xl: none;

  --scrollbar-thumb: #35463a;
  --scrollbar-thumb-hover: #465a4c;
  color-scheme: dark;
}
